// Computes the GCD of two strictly positive integers using the subtraction-based
// Euclidean algorithm.
//
// Precondition (as stated in the problem): m > 0 and n > 0.
fn gcd_i(m: i32, n: i32) -> i32 {
    debug_assert!(m > 0 && n > 0);

    let mut a = m;
    let mut b = n;

    // Invariant: a > 0 && b > 0 throughout.
    // Measure for termination: a + b strictly decreases each iteration.
    while a != b {
        if a > b {
            a -= b; // still positive because a > b >= 1
        } else {
            b -= a; // still positive because b > a >= 1
        }
    }

    a
}